mkdir -p /home/jack/.t3/bench-runs/2026-10-08-last-push-claude-fable/att-003/clone-work && cat > /home/jack/.t3/bench-runs/2026-10-08-last-push-claude-fable/att-003/clone-work/unlocal.js <<'EOF'
function oldUnlocal(date){ const s=date.toISOString().substr(0,10); const t=s.split('-'); return new Date(Number(t[0]),Number(t[1])-1,Number(t[2])) }
function newUnlocal(date){ const off=date.getTimezoneOffset()*60000; date.setTime(date.getTime()-off); const s=date.toISOString().substr(0,10); const t=s.split('-'); return new Date(Number(t[0]),Number(t[1])-1,Number(t[2])) }
// Python-side serialization of date(2019,9,20): ms at UTC midnight
const pyMs = Date.UTC(2019,8,20);
// JS-side value after _on_select: toDateString string
const jsStr = "Mon Sep 16 2019";
// Python max_date=datetime.utcnow() at 23:30 UTC
const pyLate = Date.UTC(2019,8,20,23,30);
console.log("TZ=",process.env.TZ, "offset(now)=", new Date().getTimezoneOffset());
for (const [label,v] of [["py ms (2019-09-20)",pyMs],["js str Mon Sep 16 2019",jsStr],["py datetime 2019-09-20T23:30Z",pyLate]]) {
  console.log(`  ${label}: old=${oldUnlocal(new Date(v)).toDateString()}  new=${newUnlocal(new Date(v)).toDateString()}`)
}
// argument mutation check
const d = new Date(pyMs); const before=d.getTime(); newUnlocal(d); console.log("  arg mutated:", d.getTime()!==before, "by ms", d.getTime()-before);
EOF
cd /home/jack/.t3/bench-runs/2026-10-08-last-push-claude-fable/att-003/clone-work && for tz in UTC Europe/Paris America/Los_Angeles America/New_York Pacific/Auckland; do TZ=$tz node unlocal.js; done
